 23→const MESSAGE_BRIDGE_SCRIPT = `
 24→            // Setup message bridge between Element Call and React Native
 25→            (function() {
 26→              console.log('🔧 Setting up React Native bridge...');
 27→              
 28→              // Store original postMessage
 29→              const originalPostMessage = window.postMessage.bind(window);
 30→              
 31→              // Flag to prevent re-capturing injected messages
 32→              let isInjecting = false;
 33→              
 34→              // Expose method for injecting messages without re-capture
 35→              window.__rnInjectMessage = function(message) {
 36→                isInjecting = true;
 37→                try {
 38→                  originalPostMessage(message, '*');
 39→                } finally {
 40→                  isInjecting = false;
 41→                }
 42→              };
 43→              
 44→              // Override postMessage to intercept widget messages
 45→              window.postMessage = function(message, targetOrigin) {
 46→                // Don't capture messages that we're injecting from RN
 47→                if (!isInjecting) {
 48→                  try {
 49→                    // Send to React Native if available
 50→                    if (window.ReactNativeWebView) {
 51→                      const messageStr = typeof message === 'string' 
 52→                        ? message 
 53→                        : JSON.stringify(message);
 54→                      window.ReactNativeWebView.postMessage(messageStr);
 55→                      console.log('Sent to RN:', messageStr);
 56→                    }
 57→                  } catch (e) {
 58→                    console.error('Failed to send to RN:', e);
 59→                  }
 60→                }
 61→                
 62→                // Always call original for in-page communication
 63→                try {
 64→                  originalPostMessage(message, targetOrigin);
 65→                } catch (e) {
 66→                  console.error('Failed original postMessage:', e);
 67→                }
 68→              };
 69→            
 70→              console.log('✅ React Native bridge ready');
 71→            })();
 72→            true; // Required for iOS          
 73→  `;
