 75→export const ElementCall: React.FC<
 76→  NativeStackScreenProps<Routes, "elementCall">
 77→> = ({ route, navigation }) => {
 78→  const { roomId, roomName } = route.params;
 79→  const insets = useSafeAreaInsets();
 80→  const client = MatrixService.instance;
 81→  const room = client?.getRoom(roomId);
 82→  const webViewRef = useRef<WebView>(null);
 83→  const [callUrl, setCallUrl] = useState<string | null>(null);
 84→  const [loading, setLoading] = useState(true);
 85→  const [error, setError] = useState<string | null>(null);
 86→  const messageLoopRef = useRef<boolean>(false);
 87→  const messageLoopRunningRef = useRef<boolean>(false); // Track if loop is already running
 88→  const initializingRef = useRef<boolean>(false); // Track if initialization is in progress
 89→  const [isCallEnding, setIsCallEnding] = useState(false);
 90→  const [hasMediaPermissions, setHasMediaPermissions] = useState(false);
 91→
 92→  useEffect(() => {
 93→    initializeCall();
 94→
 95→    const handleAppStateChange = (nextAppState: AppStateStatus) => {
 96→      if (nextAppState === "background" || nextAppState === "inactive") {
 97→        messageLoopRef.current = false;
 98→        messageLoopRunningRef.current = false;
 99→        ElementCallService.endCall(roomId);
100→      }
101→    };
102→
103→    const appStateSub = AppState.addEventListener(
104→      "change",
105→      handleAppStateChange,
106→    );
107→
108→    return () => {
109→      // Stop message loop and end call when component unmounts
110→      messageLoopRef.current = false;
111→      messageLoopRunningRef.current = false;
112→      initializingRef.current = false;
113→      ElementCallService.endCall(roomId);
114→      appStateSub.remove();
115→    };
116→  }, [roomId]);
117→
118→  const initializeCall = async () => {
119→    // Prevent multiple simultaneous initializations
120→    if (initializingRef.current) {
121→      console.log("Call initialization already in progress, skipping...");
122→      return;
123→    }
124→
125→    try {
126→      if (!client || !room) throw new Error("Client or room not available");
127→
128→      initializingRef.current = true;
129→      setLoading(true);
130→      setError(null);
131→
132→      // Check native permissions for camera and microphone
133→      const [cameraGranted, microphoneGranted] = await Promise.all([
134→        checkPermission(PermissionType.CAMERA),
135→        checkPermission(PermissionType.MICROPHONE),
136→      ]);
137→
138→      // Store permission status to control WebView behavior
139→      const permissionsGranted = cameraGranted && microphoneGranted;
140→      setHasMediaPermissions(permissionsGranted);
141→
142→      if (!permissionsGranted) {
143→        throw new Error(
144→          "Camera and microphone permissions are required for video calls",
145→        );
146→      }
147→
148→      const { url } = await ElementCallService.startCall(roomId, room, client);
149→
150→      setCallUrl(url);
151→
152→      setTimeout(() => {
153→        startMessageLoop();
154→      }, 1000); // Give WebView time to initialize
155→
156→      setLoading(false);
157→    } catch (err) {
158→      console.error("Failed to initialize call:", err);
159→      setError(
160→        err instanceof Error ? err.message : "Failed to initialize call",
161→      );
162→      setLoading(false);
163→      initializingRef.current = false; // Reset on error
164→    }
165→  };
166→
167→  const startMessageLoop = () => {
168→    // Prevent multiple message loops from starting
169→    if (messageLoopRunningRef.current) {
170→      console.log("Message loop already running, skipping...");
171→      return;
172→    }
173→
174→    messageLoopRef.current = true;
175→    messageLoopRunningRef.current = true;
176→
177→    // Run message loop in background (like Swift's Task.detached)
178→    const runLoop = async () => {
179→      while (messageLoopRef.current) {
180→        try {
181→          const message =
182→            await ElementCallService.receiveMessagesFromWidget(roomId);
183→
184→          // recv() returns null when widget driver is done (like Swift)
185→          if (!message) break;
186→
187→          if (webViewRef.current) {
188→            const script = `
189→              try {
190→                // Use our custom inject method to avoid re-capturing
191→                if (window.__rnInjectMessage) {
192→                  window.__rnInjectMessage(${message});
193→                } else {
194→                  window.postMessage(${message}, '*');
195→                }
196→              } catch (e) {
197→                console.error('Failed to post message:', e);
198→              }
199→            `;
200→            webViewRef.current.injectJavaScript(script);
201→          }
202→
203→          await new Promise((resolve) => setTimeout(resolve, 10));
204→        } catch (err) {
