1095→  public static getReadReceipts = async (event: EventTimelineItem) => {
1096→    const userIds = Array.from(event.readReceipts.keys()).map(
1097→      (userIds) => userIds,
1098→    );
1099→
1100→    // Don't show read receipts for the sender's own message
1101→    const filteredUserIds = userIds.filter((userId) => userId !== event.sender);
1102→
1103→    if (!filteredUserIds.length) {
1104→      return [];
1105→    }
1106→
1107→    try {
1108→      const profilePromises = filteredUserIds.map((userId) =>
1109→        this.instance?.getProfile(userId),
1110→      );
1111→      const profiles = await Promise.allSettled(profilePromises);
1112→      return profiles
1113→        .filter((p) => p.status === "fulfilled")
1114→        .map((p) => p.value)
1115→        .filter((p) => p !== undefined);
1116→    } catch (error) {
