 26→/** Get the current user ID, works in both foreground and background */
 27→const getCurrentUserId = (): string | null => {
 28→  // Try to get from active instance first (foreground)
 29→  const instanceUserId = MatrixService.instance?.userId();
 30→  if (instanceUserId) return instanceUserId;
 31→
 32→  // Fall back to stored credentials (works in background)
 33→  const credentials = MatrixStorage.getLoginCredentials();
 34→  return credentials?.userId || null;
 35→};
