 37→/**
 38→ * Ensure MatrixService is initialized for background decryption
 39→ * Uses lightweight initialization that doesn't start sync service
 40→ */
 41→const ensureServiceInitialized = async (): Promise<boolean> => {
 42→  const notificationClient = MatrixService.getNotificationClient();
 43→  if (notificationClient) return true;
 44→
 45→  // Foreground: create notification client if possible
 46→  if (MatrixService.instance) {
 47→    const client = await MatrixService.ensureNotificationClient();
 48→    return !!client;
 49→  }
 50→
 51→  // Try to restore session with lightweight background method
 52→  try {
 53→    const restored = await MatrixService.restoreSessionForBackground();
 54→    return restored;
 55→  } catch (error) {
 56→    console.error("[Push] Failed to restore session:", error);
 57→    return false;
 58→  }
 59→};
