 61→const handleReceivedMessage = async (
 62→  message: FirebaseMessagingTypes.RemoteMessage,
 63→) => {
 64→  const data = message.data as unknown as NotificationData;
 65→  if (!data) return;
 66→
 67→  // Skip notifications for own messages (works in both foreground and background)
 68→  const currentUserId = getCurrentUserId();
 69→  if (currentUserId && data.sender === currentUserId) return;
 70→
 71→  const isCallOnIOS =
 72→    Platform.OS === "ios" &&
 73→    (data.type === "m.call.invite" || data.type === "m.call.member");
 74→
 75→  if (isCallOnIOS) {
 76→    // Skip if sync-based detection already triggered CallKit for this room
 77→    if (CallKitService.isRingingForRoom(data.room_id)) return;
 78→
 79→    CallKitService.displayIncomingCall({
 80→      roomId: data.room_id,
 81→      roomName: data.room_name || data.sender_display_name || data.sender,
 82→      senderDisplayName: data.sender_display_name || data.sender,
 83→    });
 84→    return;
 85→  }
 86→
 87→  const notificationId = message.messageId || `msg_${Date.now()}`;
 88→  const formattedMessage = formatLocalPushNotificationMessage(data);
 89→
 90→  if (!formattedMessage) return;
 91→
 92→  // Decrypt encrypted messages, then check if it's a call or a regular message
 93→  if (data.type === "m.room.encrypted" && data.room_id && data.event_id) {
 94→    try {
 95→      // Always ensure service is initialized for encrypted messages
 96→      const initialized = await ensureServiceInitialized();
 97→      if (!initialized) return;
 98→
 99→      // Check if the decrypted event is a call — route to CallKit on iOS
100→      if (Platform.OS === "ios") {

100→      if (Platform.OS === "ios") {
101→        const isCall = await isDecryptedEventCall(data.room_id, data.event_id);
102→
103→        if (isCall) {
104→          // Skip if sync-based detection already triggered CallKit for this room
105→          if (CallKitService.isRingingForRoom(data.room_id)) return;
106→
107→          const roomName = MatrixService.getRoomInfo(
108→            data.room_id,
109→          )?.displayName();
110→
111→          CallKitService.displayIncomingCall({
112→            roomId: data.room_id,
113→            roomName:
114→              roomName ||
115→              data.room_name ||
116→              data.sender_display_name ||
117→              data.sender,
118→            senderDisplayName: data.sender_display_name || data.sender,
119→          });
120→          return;
121→        }
122→      }
123→
124→      const roomName = MatrixService.getRoomInfo(data.room_id)?.displayName();
125→      const decryptedContent = await getDecryptedEventContent(
126→        data.room_id,
127→        data.event_id,
128→      );
129→
130→      if (decryptedContent) {
131→        await NotifeeService.create({
132→          title:
133→            roomName ||
134→            data.room_name ||
135→            data.sender_display_name ||
136→            data.sender ||
137→            "Unknown Sender",
138→          message: `${data.sender_display_name || data.sender}: ${decryptedContent}`,
139→          id: notificationId,
140→          data: { room_id: data.room_id },
141→        });
142→      } else {
143→        await NotifeeService.create({
144→          title: formattedMessage.title,
145→          message: formattedMessage.message,
146→          id: notificationId,
147→          data: { room_id: formattedMessage.room_id },
148→        });
149→      }
150→    } catch (error) {
151→      console.error("[Push] Failed to decrypt:", error);
152→    }
153→
154→    return;
155→  }
156→
157→  // For non-encrypted messages, show directly
158→  await NotifeeService.create({
159→    title: formattedMessage.title,
160→    message: formattedMessage.message,
161→    id: notificationId,
162→    data: { room_id: formattedMessage.room_id },
163→  });
164→};
165→
166→const handleNotificationPress = (
167→  message: FirebaseMessagingTypes.RemoteMessage | null,
168→  isInitialNotification: boolean,
169→) => {
170→  const roomId = (message?.data as unknown as NotificationData)?.room_id;
171→
172→  if (!roomId || typeof roomId !== "string") return;
173→
174→  // For initial notification (cold start), store the room_id
175→  // and let the Splash screen handle navigation after session restoration
176→  if (isInitialNotification) {
177→    NotifeeService.setPendingRoomId(roomId);
178→    return;
179→  }
180→
181→  // For background events (app already running), navigate directly to room
182→  NavigationContainerRef.navigate("room", { roomId });
183→};
