185→export const PushNotificationsService = {
186→  getToken: async () => await getToken(getMessaging()),
187→  /** Register the device with Matrix homeserver for push notifications
188→   * This should be called after successful login and after push permissions */
189→  registerPusher: async () => {
190→    try {
191→      const fcmToken = await getToken(getMessaging());
192→      await MatrixService.setPusher(fcmToken);
193→      return true;
194→    } catch (error) {
195→      console.error("Failed to register push notifications:", error);
196→      throw error;
197→    }
198→  },
199→  /** Unregister the device from Matrix homeserver */
200→  unregisterPusher: async () => {
201→    try {
202→      const fcmToken = await getMessaging().getToken();
203→      await MatrixService.removePusher(fcmToken);
204→      return true;
205→    } catch (error) {
206→      console.error("Failed to unregister push notifications:", error);
207→      throw error;
208→    }
209→  },
210→  registerListeners: async () => {
211→    // Foreground message handler
212→    onMessage(getMessaging(), async (message) => {
213→      await handleReceivedMessage(message);
214→    });
215→
216→    // When the application is opened from a quit state (cold start)
217→    getInitialNotification(getMessaging()).then((remoteMessage) => {
218→      handleNotificationPress(remoteMessage, true);
219→    });
220→
221→    // When the application is running, but in the background
222→    onNotificationOpenedApp(getMessaging(), (remoteMessage) => {
223→      handleNotificationPress(remoteMessage, false);
224→    });
225→  },
226→  /** Handle background messages - called from index.js */
227→  handleBackgroundMessage: async (
228→    remoteMessage: FirebaseMessagingTypes.RemoteMessage,
229→  ) => {
230→    await handleReceivedMessage(remoteMessage);
231→  },
232→  checkPermissions: async () => {
233→    const result = await checkNotifications();
234→    return result.status === RESULTS.GRANTED;
235→  },
236→  requestPermissions: async () => {
237→    const result = await requestNotifications(["alert"]);
238→    return result.status === RESULTS.GRANTED;
