 17→/** Get the decrypted content of an encrypted event*/
 18→export const getDecryptedEventContent = async (
 19→  roomId: string,
 20→  eventId: string,
 21→): Promise<string | null> => {
 22→  try {
 23→    const notificationClient =
 24→      MatrixService.getNotificationClient() ||
 25→      (await MatrixService.ensureNotificationClient());
 26→    if (!notificationClient) return null;
 27→
 28→    const item = await MatrixService.getNotificationContent(roomId, eventId);
 29→    if (!item) return null;
 30→
 31→    return getNotificationItemContent(item);
 32→  } catch (error) {
 33→    console.warn("Failed to get decrypted event content:", error);
 34→    return null;
 35→  }
 36→};
 37→
 38→const formatMessageType = (messageType: MessageType): string | null => {
 39→  if (!messageType) return null;
 40→
 41→  switch (messageType.tag) {
 42→    case MessageType_Tags.Text:
 43→    case MessageType_Tags.Emote:
 44→    case MessageType_Tags.Notice:
 45→      return messageType.inner.content.body || "Message";
 46→    case MessageType_Tags.Image:
 47→      return "📷 Image";
 48→    case MessageType_Tags.Video:
 49→      return "🎥 Video";
 50→    case MessageType_Tags.Audio:
 51→      return "🎵 Audio";
 52→    case MessageType_Tags.File:
 53→      return "📎 File";
 54→    case MessageType_Tags.Location:
 55→      return "📍 Location";
 56→    case MessageType_Tags.Gallery:
 57→      return "📷 Gallery";
 58→    default:
 59→      return null;
 60→  }
 61→};
 62→
 63→const getNotificationItemContent = (item: NotificationItem): string | null => {
 64→  if (item.event.tag !== NotificationEvent_Tags.Timeline) return null;
 65→
 66→  const eventType = item.event.inner.event.eventType();
 67→  if (eventType.tag !== TimelineEventType_Tags.MessageLike) return null;
 68→
 69→  const content = eventType.inner.content;
 70→
 71→  switch (content.tag) {
 72→    case MessageLikeEventContent_Tags.RoomMessage:
 73→      return formatMessageType(content.inner.messageType) || "Message";
 74→    case MessageLikeEventContent_Tags.RoomEncrypted:
 75→      return null;
 76→    case MessageLikeEventContent_Tags.Sticker:
 77→      return "🧩 Sticker";
 78→    case MessageLikeEventContent_Tags.Poll:
 79→      return "📊 Poll";
 80→    case MessageLikeEventContent_Tags.ReactionContent:
 81→      return "Reacted to a message";
 82→    case MessageLikeEventContent_Tags.RoomRedaction:
 83→      return "Message deleted";
 84→    case MessageLikeEventContent_Tags.CallInvite:
 85→    case MessageLikeEventContent_Tags.RtcNotification:
 86→      return "Incoming call";
 87→    case MessageLikeEventContent_Tags.CallHangup:
 88→      return "Call ended";
 89→    default:
 90→      return null;
 91→  }
 92→};
 93→
 94→/** Check if a decrypted notification item is a call event (CallInvite or RtcNotification) */
 95→const isNotificationItemCall = (item: NotificationItem): boolean => {
 96→  if (item.event.tag !== NotificationEvent_Tags.Timeline) return false;
 97→
 98→  const eventType = item.event.inner.event.eventType();
 99→  if (eventType.tag !== TimelineEventType_Tags.MessageLike) return false;
100→
101→  const content = eventType.inner.content;
102→  return (
103→    content.tag === MessageLikeEventContent_Tags.CallInvite ||
104→    content.tag === MessageLikeEventContent_Tags.RtcNotification
105→  );
106→};
