 13→  navigation,
 14→}) => {
 15→  const { roomId } = route.params;
 16→  const client = MatrixService.instance;
 17→  const room = useMemo(() => client?.getRoom(roomId), [client, roomId]);
 18→  const insets = useSafeAreaInsets();
 19→  const hasActiveCall = useMemo(() => room?.hasActiveRoomCall(), [room]);
 20→  const [roomInfo, setRoomInfo] = useState<RoomInfo | undefined>(undefined);
 21→  const [isInviteAccepted, setIsInviteAccepted] = useState(false);
 22→  const isRoomInvite = useMemo(() => {
 23→    return roomInfo?.membership === Membership.Invited && !isInviteAccepted;
 24→  }, [roomInfo, isInviteAccepted]);
 25→
 26→  const { isMembersLoading, roomMembers, hasNoCallOption } =
 27→    useRoomInitialization({ room });
 28→
 29→  useEffect(() => {
 30→    room?.roomInfo().then(setRoomInfo).catch(console.error);
 31→  }, [room]);
 32→
 33→  const handleStartCall = () => {
 34→    if (!client || !room) {
 35→      console.error("Client or room not available");
 36→      return;
 37→    }
 38→
 39→    navigation.navigate("elementCall", {
 40→      roomId,
 41→      roomName: room.displayName(),
 42→    });
 43→  };
 44→
 45→  const handleInviteAccepted = () => {
 46→    setIsInviteAccepted(true);
 47→  };
 48→
 49→  const handleInviteDeclined = () => {
 50→    navigation.goBack();
 51→  };
 52→
 53→  const handleRoomDetails = () => {
